{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Weights the contribution of model-based and model-free values for stage-1 choices.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "separate_betas",
      "title": "Separate Stage Inverse Temperatures",
      "description": "Uses distinct inverse temperature parameters for stage-1 and stage-2 softmax choices.",
      "params": [
        {
          "name": "beta1",
          "bounds": [0, 10]
        },
        {
          "name": "beta2",
          "bounds": [0, 10]
        }
      ],
      "evidence": "logits_1 = beta1 * q_stage1_net\n...\nlogits_2 = beta2 * q_stage2_mf[state_idx].copy()",
      "expressible_in_slots": true
    },
    {
      "name": "stage1_perseveration",
      "title": "Stage 1 Choice Perseveration",
      "description": "Adds a stickiness bonus to the stage-1 action chosen on the previous trial.",
      "params": [
        {
          "name": "p1",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "if last_action_1 != -1:\n            logits_1[last_action_1] += p1",
      "expressible_in_slots": true
    },
    {
      "name": "stage2_perseveration",
      "title": "Stage 2 Choice Perseveration",
      "description": "Adds a stickiness bonus to the stage-2 action chosen on the previous trial in the same state.",
      "params": [
        {
          "name": "p2",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "if last_action_2[state_idx] != -1:\n            logits_2[last_action_2[state_idx]] += p2",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates the stage-1 model-free value using the stage-2 reward prediction error scaled by a trace parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += alpha * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "value_decay",
      "title": "Value Decay",
      "description": "Decays the Q-values of all unchosen actions towards an initial value of 0.5.",
      "params": [
        {
          "name": "decay",
          "bounds": [0, 1]
        }
      ],
      "evidence": "unchosen_1 = 1 - action_1[trial]\n        q_stage1_mf[unchosen_1] += decay * (0.5 - q_stage1_mf[unchosen_1])\n        \n        for s in range(2):\n            for a in range(2):\n                if not (s == state_idx and a == action_2[trial]):\n                    q_stage2_mf[s, a] += decay * (0.5 - q_stage2_mf[s, a])",
      "expressible_in_slots": true
    },
    {
      "name": "neutral_q_init",
      "title": "Neutral Q-Initialization",
      "description": "Initializes all Q-values to 0.5 instead of 0.",
      "params": [],
      "evidence": "q_stage1_mf = np.zeros(2) + 0.5\n    q_stage2_mf = np.zeros((2, 2)) + 0.5",
      "expressible_in_slots": true
    }
  ]
}
